sessions = []
scripts = []


def on_message(message, data):
    kind = message.get("type")
    if kind == "send" or kind == "log":
        text = message.get("payload")
    elif kind == "error":
        text = message.get("stack") or message.get("description")
    else:
        return
    if not isinstance(text, str):
        text = str(text)
    print(text, flush=True)


def attach_pid(pid):
    print("开始挂载 %s" % pid, flush=True)
    session = frida.attach(int(pid))
    script = session.create_script(JS)
    script.on("message", on_message)
    script.load()
    sessions.append(session)
    scripts.append(script)
    print("已挂载 %s" % pid, flush=True)


def main():
    if len(sys.argv) < 2 or not sys.argv[1].strip():
        print("参数错误，请参照使用说明", flush=True)
        return 0
    pids = [part.strip() for part in sys.argv[1].split(",") if part.strip()]
    if not pids:
        print("参数错误，请参照使用说明", flush=True)
        return 0
    attached = 0
    for pid in pids:
        try:
            attach_pid(pid)
            attached += 1
        except Exception as e:
            print("进程 %s 没有挂上：%s" % (pid, e), flush=True)
            print("这个进程上如果已经有别的 frida，不能再挂一次。", flush=True)
    if attached == 0:
        print("一个都没挂上", flush=True)
        return 1
    while True:
        time.sleep(1)


if __name__ == "__main__":
    sys.exit(main())
